--DECLARE
@PROV1 	CHAR(11),  
@PROV2 CHAR(11),  
@ART1 CHAR(20),  
@ART2 CHAR(20),  
@FEC1 NUMERIC(15,6),
@FEC2 NUMERIC(15,6)
/*
